/** Real, source-qualified research journeys on an isolated X11 display. No fixture data. */
public final class ResearchAcceptance {
  static final List<String> deferred=new ArrayList<>();
  interface Condition {boolean ready()throws Exception;}
  static void until(Condition condition,String description)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);while(System.nanoTime()<end){if(condition.ready())return;Thread.sleep(100);}throw new AssertionError("Timed out: "+description);}
  static void check(boolean value,String text){JournalSnapshots.check(value,text);}
  static void defer(boolean value,String text){if(value)check(true,text);else{deferred.add(text);JournalSnapshots.report.add("FAIL (deferred): "+text);}}
  static JTabbedPane tabs(String title)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JTabbedPane pane&&pane.isShowing()&&java.util.stream.IntStream.range(0,pane.getTabCount()).anyMatch(i->pane.getTitleAt(i).equals(title))).map(c->(JTabbedPane)c).findFirst().orElseThrow());}
  static void tab(String title)throws Exception{JTabbedPane pane=tabs(title);int index=JournalSnapshots.edt(()->java.util.stream.IntStream.range(0,pane.getTabCount()).filter(i->pane.getTitleAt(i).equals(title)).findFirst().orElseThrow());Point point=JournalSnapshots.edt(()->{Rectangle bounds=pane.getBoundsAt(index);Point p=pane.getLocationOnScreen();p.translate(bounds.x+bounds.width/2,bounds.y+bounds.height/2);return p;});JournalSnapshots.robot.mouseMove(point.x,point.y);JournalSnapshots.robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);JournalSnapshots.robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);JournalSnapshots.robot.waitForIdle();JournalSnapshots.robot.delay(300);check(JournalSnapshots.edt(pane::getSelectedIndex)==index,"Native tab selected: "+title);}
  static void open(EntityKind kind,long id)throws Exception{JournalSnapshots.edt(()->{JournalSnapshots.controller.open(new ViewTarget.Entity(new EntityRef(kind,id)));return null;});if(kind==EntityKind.ITEM)loadedItem(id);}
  static void loadedItem(long id)throws Exception{until(()->JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(c->c instanceof dev.wowforever.app.ui.detail.HeaderPanel h&&h.isShowing()&&("Item #"+id).equals(h.subtitle()))),"loaded exact item header "+id);}
  static void target(EntityKind kind,long id)throws Exception{until(()->JournalSnapshots.edt(()->JournalSnapshots.controller.current() instanceof ViewTarget.Entity e&&e.ref().equals(new EntityRef(kind,id))),"exact "+kind+" "+id);}
  static void sizes(String name)throws Exception{for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{JournalSnapshots.frame.setSize(width,900);return null;});JournalSnapshots.snap(name+"-"+width);if(name.equals("city-1519-people-services")&&width==420)defer(JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JToggleButton b&&List.of("All recorded people","Vendors","Quest connections").contains(b.getText())).allMatch(c->c.getY()>=0&&c.getY()+c.getHeight()<=c.getParent().getHeight())),"Compact city service filters remain inside their visible layout bounds");}JournalSnapshots.edt(()->{JournalSnapshots.frame.setSize(1280,900);return null;});}
  static JButton prefix(String text)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JButton b&&b.isShowing()&&b.getText()!=null&&b.getText().startsWith(text)).map(c->(JButton)c).findFirst().orElseThrow());}
  static void key(int code){JournalSnapshots.robot.keyPress(code);JournalSnapshots.robot.keyRelease(code);JournalSnapshots.robot.delay(250);}
  static String text()throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.texts(JournalSnapshots.frame));}
  public static void main(String[] args)throws Exception{
    if(args.length!=3||GraphicsEnvironment.isHeadless())throw new IllegalArgumentException("REVIEW_JAR DATABASE EMPTY_OUTPUT (isolated X11)");Path out=Path.of(args[2]);Files.createDirectories(out);try(var files=Files.list(out)){if(files.findAny().isPresent())throw new IllegalArgumentException("Output must be empty");}JournalSnapshots.out=out;
    var report=JournalSnapshots.report;report.add("Created: "+Instant.now());report.add("JAR SHA-256: "+JournalSnapshots.hash(Path.of(args[0])));report.add("Scope: real JFrame/Robot isolated X11, actual database research; city music disabled; no desktop Wayland claim");ExecutorService worker=Executors.newSingleThreadExecutor();
    try(var db=Database.open(Path.of(args[1]))){report.add("Database build: "+db.meta().get("build_id"));var repos=Repositories.of(db);
      var reward=repos.items().detail(211527).orElseThrow().rewardFrom().stream().filter(s->s.ref().kind()==EntityKind.QUEST).findFirst().orElseThrow();var chain=repos.quests().chain(reward.ref().id());check(chain.steps().size()==7,"Actual Sleeping Bag research graph has seven quest nodes");check(chain.steps().stream().filter(s->s.parentQuestId()!=null&&!chain.evidenceFor(s).isEmpty()).count()==6,"Actual Sleeping Bag graph has six source-attributed links");
      var recipes=new NativeRecipeGuideRepository(db).forItem(251525);var recipe=recipes.recipes().stream().filter(r->r.skills().stream().anyMatch(s->s.name().equals("Cooking"))).findFirst().orElseThrow();var ingredient=recipe.ingredients().stream().filter(i->i.count()!=null&&i.count()>0).findFirst().orElseThrow();
      var city=new CityServicesRepository(db).load(1519);var vendor=city.people().stream().filter(p->!p.stock().isEmpty()).findFirst().orElseThrow();var giver=city.people().stream().filter(p->!p.quests().isEmpty()).findFirst().orElseThrow();
      JournalSnapshots.edt(()->{Fonts.install();ThemeManager.apply(ThemeManager.Mode.DARK);JournalSnapshots.frame=new MainFrame(UiExperience.JOURNAL);JournalSnapshots.controller=JournalSnapshots.wire(JournalSnapshots.frame,db,worker);JournalSnapshots.frame.setBounds(20,20,1280,900);JournalSnapshots.frame.setVisible(true);return null;});JournalSnapshots.robot=new Robot();JournalSnapshots.robot.setAutoDelay(55);
      open(EntityKind.ZONE,1519);JournalSnapshots.waitFor(JournalCityPage.class);tab("People & services");until(()->text().contains("Recorded city coordinates"),"actual recorded city placements");check(text().contains("not complete city service coverage")&&text().contains("Questie NPC locations"),"City directory qualifies placement/vendor/quest sources and coverage");sizes("city-1519-people-services");
      JournalSnapshots.click(JournalSnapshots.toggle("Vendors"));JPanel vendorCard=personCard(vendor.name());var stock=vendor.stock().getFirst();JournalSnapshots.click(cardButton(vendorCard,label(stock.name(),"Item",stock.id())));target(EntityKind.ITEM,stock.id());loadedItem(stock.id());check(true,"Actual city vendor stock link opens exact item ID");JournalSnapshots.back();JournalSnapshots.waitFor(JournalCityPage.class);check(JournalSnapshots.edt(()->tabsUnchecked("People & services").getTitleAt(tabsUnchecked("People & services").getSelectedIndex())).equals("People & services"),"Back restores city directory tab");
      JournalSnapshots.click(JournalSnapshots.toggle("Quest connections"));JPanel questCard=personCard(giver.name());var quest=giver.quests().getFirst();JournalSnapshots.click(cardButton(questCard,quest.role()+": "+label(quest.name(),"Quest",quest.id())));target(EntityKind.QUEST,quest.id());JournalSnapshots.waitFor(QuestPage.class);check(true,"Actual city quest connection opens exact quest ID");
      open(EntityKind.ITEM,211527);tab("Research trail");until(()->JournalSnapshots.find(ChainPanel.class)!=null,"lazy actual quest chain");ChainPanel panel=JournalSnapshots.find(ChainPanel.class);for(int pass=0;pass<3;pass++){var expansion=JournalSnapshots.edt(()->panel.rows().stream().filter(r->r.kind()==ChainRows.Kind.SHOW_EARLIER||r.kind()==ChainRows.Kind.SHOW_LATER).findFirst());if(expansion.isEmpty())break;JournalSnapshots.click(JournalSnapshots.button(expansion.orElseThrow().text()));}
      check(JournalSnapshots.edt(()->panel.rows().stream().filter(r->r.step()!=null).map(r->r.step().questId()).distinct().count())==7,"Research trail renders all seven actual quest nodes after expansion");sizes("item-211527-research-trail");JournalSnapshots.click(prefix("Open quest: "));target(EntityKind.QUEST,reward.ref().id());JournalSnapshots.waitFor(QuestPage.class);JournalSnapshots.back();JournalSnapshots.waitFor(ChainPanel.class);check(JournalSnapshots.edt(()->tabsUnchecked("Research trail").getTitleAt(tabsUnchecked("Research trail").getSelectedIndex())).equals("Research trail"),"Back restores selected Research trail section");
      open(EntityKind.ITEM,251525);tab("Crafting guide");JournalSnapshots.waitFor(RecipeFieldGuidePanel.class);until(()->text().contains("Cooking")&&text().contains("Reagents"),"native Cooking and reagent evidence");check(text().contains("Forever build 1.60.1.70450")&&text().contains(ingredient.name()),"Crafting guide presents exact Forever Cooking recipe and real reagent");sizes("item-251525-crafting-guide");JButton ingredientButton=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JButton b&&b.isShowing()&&("Inspect "+ingredient.count()+" × "+ingredient.name()).equals(b.getAccessibleContext().getAccessibleName())).map(c->(JButton)c).findFirst().orElseThrow());JournalSnapshots.click(ingredientButton);target(EntityKind.ITEM,ingredient.itemId());loadedItem(ingredient.itemId());JournalSnapshots.back();JournalSnapshots.waitFor(RecipeFieldGuidePanel.class);check(JournalSnapshots.edt(()->tabsUnchecked("Crafting guide").getTitleAt(tabsUnchecked("Crafting guide").getSelectedIndex())).equals("Crafting guide"),"Back restores selected Crafting guide");
      JournalSnapshots.edt(()->{JournalSnapshots.controller.open(new ViewTarget.Forever("lore"));return null;});JournalSnapshots.waitFor(JournalLoreSearchPage.class);JTextField query=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JTextField f&&"lore-query".equals(f.getName())).map(c->(JTextField)c).findFirst().orElseThrow());JournalSnapshots.edt(()->{query.setText("Dalaran");return null;});until(()->JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(c->c instanceof JButton b&&b.isShowing()&&b.getText()!=null&&b.getText().contains(" · Quest #"))),"debounced actual Dalaran quest-text hits");check(text().contains("Questie normalized quest titles and objectives · revision")&&text().contains(db.meta().get("build_id")),"Quest text hits show source revision and database build");check(JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(c->c instanceof JTextArea area&&area.isShowing()&&area.getHighlighter().getHighlights().length>0)),"Actual quest-text matches are highlighted");sizes("quest-text-dalaran");JButton hit=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JButton b&&b.isShowing()&&b.getText()!=null&&b.getText().contains(" · Quest #")).map(c->(JButton)c).findFirst().orElseThrow());long hitId=Long.parseLong(JournalSnapshots.edt(hit::getText).substring(JournalSnapshots.edt(hit::getText).lastIndexOf('#')+1));JournalSnapshots.click(hit);target(EntityKind.QUEST,hitId);JournalSnapshots.waitFor(QuestPage.class);JournalSnapshots.back();JournalSnapshots.waitFor(JournalLoreSearchPage.class);check(JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JTextField f&&"lore-query".equals(f.getName())).map(c->((JTextField)c).getText()).findFirst().orElseThrow()).equals("Dalaran"),"Back restores quest-text search query");
      open(EntityKind.ITEM,251525);JournalSnapshots.robot.keyPress(KeyEvent.VK_CONTROL);key(KeyEvent.VK_D);JournalSnapshots.robot.keyRelease(KeyEvent.VK_CONTROL);JournalSnapshots.edt(()->{JournalSnapshots.controller.open(new ViewTarget.Forever("pinned"));return null;});JournalSnapshots.waitFor(PinnedResearchPage.class);JList<?> pins=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JList<?> list&&"Pinned research references".equals(list.getAccessibleContext().getAccessibleName())).map(c->(JList<?>)c).findFirst().orElseThrow());check(JournalSnapshots.edt(()->pins.getModel().getSize())==1,"Native Ctrl+D saves current exact item in Pinned research");var context=JournalSnapshots.catalogSession.token().context();String scope=context.editionId()+"\n"+context.projectionId()+"\n"+context.clientBuild()+"\n"+context.locale();check(new PinnedResearch(UiState.loadJournal(),scope).references().size()==1&&new PinnedResearch(UiState.loadJournal(),"foreign-edition-build").references().isEmpty(),"Actual pinned reference belongs only to current game/build scope");sizes("pinned-research");JournalSnapshots.edt(()->{pins.setSelectedIndex(0);pins.requestFocusInWindow();return null;});key(KeyEvent.VK_ENTER);target(EntityKind.ITEM,251525);loadedItem(251525);check(true,"Native Enter opens exact pinned item");JournalSnapshots.back();JournalSnapshots.waitFor(PinnedResearchPage.class);JList<?> restoredPins=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JList<?> list&&"Pinned research references".equals(list.getAccessibleContext().getAccessibleName())).map(c->(JList<?>)c).findFirst().orElseThrow());JournalSnapshots.edt(()->{restoredPins.setSelectedIndex(0);restoredPins.requestFocusInWindow();return null;});key(KeyEvent.VK_DELETE);check(JournalSnapshots.edt(()->restoredPins.getModel().getSize())==0,"Native Delete removes pinned reference");
      open(EntityKind.ITEM,251525);gamePicker();if(!deferred.isEmpty())throw new AssertionError("Deferred layout failures: "+deferred);
    }catch(Throwable failure){report.add("FAIL: "+failure);throw failure;}finally{if(JournalSnapshots.frame!=null)JournalSnapshots.edt(()->{JournalSnapshots.frame.dispose();return null;});worker.shutdownNow();Files.write(out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(0);
  }
  static String label(String name,String kind,long id){return name==null||name.isBlank()?kind+" #"+id:name;}
  static JPanel personCard(String name)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JButton b&&b.isShowing()&&(name+"  ›").equals(b.getText())).map(c->(JPanel)c.getParent()).findFirst().orElseThrow());}
  static JButton cardButton(JPanel card,String text)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(card).stream().filter(c->c instanceof JButton b&&text.equals(b.getText())).map(c->(JButton)c).findFirst().orElseThrow());}
  static JTabbedPane tabsUnchecked(String title){return JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JTabbedPane pane&&pane.isShowing()&&java.util.stream.IntStream.range(0,pane.getTabCount()).anyMatch(i->pane.getTitleAt(i).equals(title))).map(c->(JTabbedPane)c).findFirst().orElseThrow();}
  static void gamePicker()throws Exception{
    var before=JournalSnapshots.catalogSession.token();JTabbedPane existing=tabs("Item & acquisition");JMenu settings=JournalSnapshots.edt(()->Arrays.stream(JournalSnapshots.frame.getJMenuBar().getSubElements()).filter(e->e instanceof JMenu menu&&menu.getText().equals("Settings")).map(e->(JMenu)e).findFirst().orElseThrow());JournalSnapshots.click(settings);JMenuItem pickerItem=JournalSnapshots.edt(()->Arrays.stream(settings.getMenuComponents()).filter(c->c instanceof JMenuItem item&&"game-catalog-menu".equals(item.getName())).map(c->(JMenuItem)c).findFirst().orElseThrow());JournalSnapshots.click(pickerItem);
    var picker=JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(w->JournalSnapshots.all(w).stream()).filter(c->c instanceof dev.wowforever.app.catalog.EditionPicker).map(c->(dev.wowforever.app.catalog.EditionPicker)c).findFirst().orElseThrow());List<JRadioButton> choices=JournalSnapshots.edt(()->JournalSnapshots.all(picker).stream().filter(JRadioButton.class::isInstance).map(JRadioButton.class::cast).toList());check(choices.size()==4&&JournalSnapshots.edt(()->choices.stream().filter(AbstractButton::isEnabled).count())==1,"Game catalog enables only installed Forever; three other games stay unavailable");JRadioButton forever=choices.stream().filter(b->"edition-forever".equals(b.getName())).findFirst().orElseThrow();JournalSnapshots.click(forever);check(JournalSnapshots.catalogSession.token().equals(before),"Clicking current game does not change catalog generation");JournalSnapshots.snap("settings-game-catalog");JButton ok=JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(w->JournalSnapshots.all(w).stream()).filter(c->c instanceof JButton b&&"OK".equals(b.getText())).map(c->(JButton)c).findFirst().orElseThrow());JournalSnapshots.click(ok);check(tabs("Item & acquisition")==existing,"Selecting current Forever game preserves current page without reload");
  }
}
